const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const suite_code =
  text(input.suite_code || 'mocked_e2e');
const case_code =
  text(input.case_code);
const clinic_name =
  text(
    input.clinic_name ||
    'کلینیک تست یکپارچه'
  );
const requested_by =
  text(
    input.requested_by ||
    'integration-tester'
  );
const webhook_base_url =
  text(
    input.webhook_base_url ||
    'http://n8n:5678/webhook'
  ).replace(/\/+$/, '');
const confirm_run =
  bool(input.confirm_run);

const errors = [];

for (const [field, value] of [
  ['suite_code', suite_code],
  ['case_code', case_code],
  ['clinic_name', clinic_name],
  ['requested_by', requested_by],
]) {
  if (!value) {
    errors.push({
      field,
      message: `${field} الزامی است.`,
    });
  }
}

if (!/^https?:\/\/.+/i.test(webhook_base_url)) {
  errors.push({
    field: 'webhook_base_url',
    message: 'آدرس Webhook معتبر نیست.',
  });
}

if (confirm_run !== true) {
  errors.push({
    field: 'confirm_run',
    message: 'اجرای تست باید تأیید شود.',
  });
}

return [{
  json: {
    suite_code,
    case_code,
    clinic_name,
    requested_by,
    webhook_base_url,
    confirm_run,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

const prepared =
  $('Prepare Gateway Test Request').first().json;

const response = $json || {};
const expected =
  prepared.expected_assertions || {};

const findByKey = (
  value,
  targetKey
) => {
  if (
    !value ||
    typeof value !== 'object'
  ) {
    return undefined;
  }

  if (
    Object.prototype.hasOwnProperty.call(
      value,
      targetKey
    )
  ) {
    return value[targetKey];
  }

  for (const nested of Object.values(value)) {
    if (
      nested &&
      typeof nested === 'object'
    ) {
      const found =
        findByKey(
          nested,
          targetKey
        );

      if (found !== undefined) {
        return found;
      }
    }
  }

  return undefined;
};

const stringifyAll = (value) => {
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
};

const assertions = [];

if (
  Object.prototype.hasOwnProperty.call(
    expected,
    'success'
  )
) {
  const actual =
    response.success === true;

  assertions.push({
    assertion: 'success',
    expected: expected.success,
    actual,
    passed:
      actual === expected.success,
  });
}

if (expected.response_contains) {
  const completeText =
    stringifyAll(response);

  assertions.push({
    assertion:
      'response_contains',
    expected:
      expected.response_contains,
    actual:
      completeText,
    passed:
      completeText.includes(
        String(
          expected.response_contains
        )
      ),
  });
}

if (expected.conversation_status) {
  const actual =
    findByKey(
      response,
      'conversation_status'
    );

  assertions.push({
    assertion:
      'conversation_status',
    expected:
      expected.conversation_status,
    actual:
      actual ?? null,
    passed:
      actual ===
      expected.conversation_status,
  });
}

if (expected.result) {
  const actual =
    findByKey(
      response,
      'result'
    );

  assertions.push({
    assertion: 'result',
    expected:
      expected.result,
    actual:
      actual ?? null,
    passed:
      actual === expected.result,
  });
}

const passed =
  assertions.length > 0 &&
  assertions.every(
    (assertion) =>
      assertion.passed === true
  );

return [{
  json: {
    run_id:
      Number(prepared.run_id),
    run_key:
      prepared.run_key,
    case_id:
      Number(prepared.case_id),
    case_code:
      prepared.case_code,
    case_title:
      prepared.case_title,
    test_status:
      passed
        ? 'passed'
        : 'failed',
    duration_ms:
      Math.max(
        0,
        Date.now() -
        Number(
          prepared.test_started_at_ms ||
          Date.now()
        )
      ),
    request_payload:
      prepared.gateway_payload,
    request_payload_text:
      JSON.stringify(
        prepared.gateway_payload
      ),
    response_payload:
      response,
    response_payload_text:
      JSON.stringify(response),
    assertion_results:
      assertions,
    assertion_results_text:
      JSON.stringify(assertions),
    error_message:
      passed
        ? ''
        : 'One or more assertions failed.',
  },
}];
